\copy (SELECT t.name, COALESCE((SELECT string_agg(tf.path, chr(124)) FROM (SELECT path FROM torrent_files WHERE info_hash = t.info_hash ORDER BY index LIMIT 10) tf), '') AS sample_paths, COALESCE(t.extension, (SELECT string_agg(DISTINCT tf.extension, chr(44)) FROM (SELECT extension FROM torrent_files WHERE info_hash = t.info_hash ORDER BY index LIMIT 20) tf WHERE tf.extension IS NOT NULL), '') AS extensions FROM torrents t ORDER BY t.created_at DESC) TO './scratch/titles_with_files.csv' WITH (FORMAT CSV, HEADER FALSE)
